def fill_between_markers(grid, marker, fill, bg=None):
    """In every row and column, fill each run of background cells bounded by markers on both sides with fill."""
    if bg is None: bg = grid[0][0]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for i in range(h):
        js = [j for j in range(w) if grid[i][j] == marker]
        for a, b in zip(js, js[1:]):
            if all(grid[i][j] == bg for j in range(a + 1, b)):
                for j in range(a + 1, b): out[i][j] = fill
    for j in range(w):
        iss = [i for i in range(h) if grid[i][j] == marker]
        for a, b in zip(iss, iss[1:]):
            if all(grid[i][j] == bg for i in range(a + 1, b)):
                for i in range(a + 1, b): out[i][j] = fill
    return out

